#!/usr/bin/env node
//
// Render data/flight-phases.yaml into firmware/gen/oa_states.h.
//
// The flight state enumeration has four consumers: this firmware, the log
// format, the packet format, and the homepage animation. Three of those were
// checked against the YAML and the fourth was not, because the header said it
// was generated by this file and this file did not exist. It carried a note
// admitting as much, which is honest and is not a check: a hand-written copy of
// a YAML table drifts from it silently, and the value that drifts is the wire
// value in every packet header and every log record.
//
//   node tools/gen-states.mjs           write the header
//   node tools/gen-states.mjs --check   exit 1 if the committed file is stale
//
// The output is byte-identical to what was committed by hand, minus that note.
// That was the point of writing it to a fixed shape.

import { readFileSync, writeFileSync, existsSync } from 'node:fs'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { parse } from 'yaml'

const ROOT = fileURLToPath(new URL('..', import.meta.url))
const SRC = join(ROOT, 'data/flight-phases.yaml')
const OUT = join(ROOT, 'firmware/gen/oa_states.h')

const data = parse(readFileSync(SRC, 'utf8'))
const phases = [...(data.phases ?? [])].sort((a, b) => a.order - b.order)

const errors = []
if (phases.length === 0) errors.push('data/flight-phases.yaml defines no phases')

// The order values are wire values. A duplicate or a gap is not a formatting
// problem, it is two states that decode as one, or a receiver that meets a
// number the table says nothing about.
const seen = new Set()
phases.forEach((p, i) => {
  if (!/^[A-Z][A-Z0-9_]*$/.test(p.id ?? '')) {
    errors.push(`phase ${i}: id "${p.id}" is not a C identifier in the shape the enum needs`)
  }
  if (!Number.isInteger(p.order) || p.order < 0 || p.order > 255) {
    errors.push(`phase ${p.id}: order ${p.order} is not a byte`)
  }
  if (seen.has(p.order)) errors.push(`phase ${p.id}: order ${p.order} is already used`)
  seen.add(p.order)
  if (p.order !== i) {
    errors.push(`phase ${p.id}: order ${p.order} leaves a gap. The enum is contiguous from 0.`)
  }
})

// transitions_to has to name a real phase. LANDED is terminal and names itself,
// because a table entry every consumer had to special-case would be
// special-cased wrongly by one of them.
const ids = new Set(phases.map((p) => p.id))
const last = phases[phases.length - 1]
for (const p of phases) {
  const next = p.transitions_to ?? (p === last ? p.id : null)
  if (next === null) errors.push(`phase ${p.id}: no transitions_to, and it is not the last phase`)
  else if (!ids.has(next)) errors.push(`phase ${p.id}: transitions_to "${next}" is not a phase`)
}

if (errors.length) {
  for (const e of errors) console.error(`error ${e}`)
  process.exit(1)
}

// Column widths from the widest row, so the committed file is stable under a
// rename rather than reflowing every line whenever one id grows.
const w = (f) => Math.max(...phases.map((p) => f(p).length))
const wSym = w((p) => p.id + ',')
const wId = w((p) => `"${p.id}",`)
const wName = w((p) => `"${p.name}",`)
// Column the line-continuation backslashes sit in.
const CONT = 70

const rows = phases.map((p, i) => {
  const next = p.transitions_to ?? p.id
  const body =
    `    X(${(p.id + ',').padEnd(wSym)} ${p.order}, ` +
    `${`"${p.id}",`.padEnd(wId)} ${`"${p.name}",`.padEnd(wName)} ${next})`
  // Every line but the last continues the macro. The backslashes line up in one
  // column, chosen from the widest row and held there so a rename reflows one
  // line rather than all of them.
  return i === phases.length - 1 ? body : body.padEnd(CONT) + '\\'
})

const header = `/*
 * GENERATED FILE. DO NOT HAND-EDIT.
 *
 * Source:    data/flight-phases.yaml
 * Generator: tools/gen-states.mjs
 * Target:    firmware/gen/oa_states.h
 *
 * The flight state enumeration has four consumers: this firmware, the log
 * format, the packet format, and the homepage animation. data/flight-phases.yaml
 * is the one definition, and this header is a rendering of it. Edit the YAML and
 * regenerate; an edit made here is lost the next time the generator runs, and
 * worse, it is lost silently while the two definitions disagree.
 *
 * \`make data\` fails when the committed file stops matching the YAML.
 */

#ifndef OAPOGEE_GEN_OA_STATES_H
#define OAPOGEE_GEN_OA_STATES_H

#include "oapogee/oa_types.h"

#ifdef __cplusplus
extern "C" {
#endif

/* Schema version of data/flight-phases.yaml this file was generated from. */
#define OA_STATES_SCHEMA_VERSION (${data.schema_version})

/* ---------------------------------------------------------------------------
 * The table.
 *
 * X(SYM, order, id_string, name_string, NEXT_SYM)
 *
 * \`order\` is the wire value: it is what goes in the packet header's state byte
 * and in the flight record's state field, and receivers and readers depend on
 * it. Values ${phases.length} to 255 are reserved; a receiver that meets one displays the
 * number rather than guessing.
 *
 * NEXT_SYM is the single successor from \`transitions_to\`. ${last.id} is terminal
 * until a power cycle, and names itself, because a table entry that had to be
 * special-cased by every consumer would be special-cased wrongly by one of them.
 * A consumer that cares about terminality tests SYM == NEXT_SYM.
 *
 * The transition criteria are not in this table. They are prose in the YAML
 * because the shape of each rule is a design decision, and every threshold they
 * need is unmeasured and lives in oa_config_t as unset.
 * ------------------------------------------------------------------------ */

#define OA_STATE_LIST(X)${' '.repeat(CONT - '#define OA_STATE_LIST(X)'.length)}\\
${rows.join('\n')}

#define OA_STATE_ENUMERATOR(SYM, order, id, name, NEXT) OA_STATE_##SYM = (order),

typedef enum {
    OA_STATE_LIST(OA_STATE_ENUMERATOR)
    OA_STATE_COUNT = ${phases.length}
} oa_state_t;

#undef OA_STATE_ENUMERATOR

/* The last defined state value. Values above this are reserved and a decoder
 * must pass them through rather than treating them as an error. */
#define OA_STATE_MAX_DEFINED (OA_STATE_${last.id})

/* The id string exactly as it appears in data/flight-phases.yaml, for the serial
 * console and for test failure messages. Returns NULL for an undefined value,
 * rather than a placeholder, so a caller cannot print something that reads like
 * a state name for a number that is not a state. */
const char *oa_state_id(oa_state_t state);

/* The human name from the YAML, for anything an operator reads. NULL under the
 * same rule. */
const char *oa_state_name(oa_state_t state);

/* True when \`value\` is one of the defined states. A receiver-side decoder wants
 * this; the state machine itself never produces an undefined value. */
bool oa_state_is_defined(uint8_t value);

#ifdef __cplusplus
}
#endif

#endif /* OAPOGEE_GEN_OA_STATES_H */
`

if (process.argv.includes('--check')) {
  if (!existsSync(OUT)) {
    console.error('error firmware/gen/oa_states.h is missing. Run `node tools/gen-states.mjs`.')
    process.exit(1)
  }
  if (readFileSync(OUT, 'utf8') !== header) {
    console.error(
      'error firmware/gen/oa_states.h does not match data/flight-phases.yaml. ' +
        'Run `node tools/gen-states.mjs` and commit the result.'
    )
    process.exit(1)
  }
  console.log(`firmware/gen/oa_states.h matches data/flight-phases.yaml, ${phases.length} states.`)
} else {
  writeFileSync(OUT, header)
  console.log(`Wrote firmware/gen/oa_states.h, ${phases.length} states.`)
}
